// kindOf is the kind of q, when q is one of the types above: not a
// pointer to one, and not a type that embeds one.
func kindOf(q Query) (Kind, bool) {
	switch q.(type) {
	case ActionDefinition:
		return KindActionDefinition, true
	case ActionRunsUsing:
		return KindActionRunsUsing, true
	case CheckoutExecuted:
		return KindCheckoutExecuted, true
	case DependabotVersionUpdates:
		return KindDependabotVersionUpdates, true
	case DownloadExecuted:
		return KindDownloadExecuted, true
	case GitCommitContains:
		return KindGitCommitContains, true
	case GitCommitRef:
		return KindGitCommitRef, true
	case GitCommitTags:
		return KindGitCommitTags, true
	case GitRefCommit:
		return KindGitRefCommit, true
	case PackageAdvisories:
		return KindPackageAdvisories, true
	case RenovateManagerEnabled:
		return KindRenovateManagerEnabled, true
	case RepoActionList:
		return KindRepoActionList, true
	case RepoAllowForking:
		return KindRepoAllowForking, true
	case RepoAllowedActions:
		return KindRepoAllowedActions, true
	case RepoArchived:
		return KindRepoArchived, true
	case RepoConfigurationVariables:
		return KindRepoConfigurationVariables, true
	case RepoDefaultTokenWrite:
		return KindRepoDefaultTokenWrite, true
	case RepoEnvironmentConfigurationVariables:
		return KindRepoEnvironmentConfigurationVariables, true
	case RepoEnvironmentProtected:
		return KindRepoEnvironmentProtected, true
	case RepoForkPRAppChecks:
		return KindRepoForkPRAppChecks, true
	case RepoForkPRRunWorkflows:
		return KindRepoForkPRRunWorkflows, true
	case RepoForkPRSecrets:
		return KindRepoForkPRSecrets, true
	case RepoForkPRWriteTokens:
		return KindRepoForkPRWriteTokens, true
	case RepoMergeCommitAppChecks:
		return KindRepoMergeCommitAppChecks, true
	case RepoPublic:
		return KindRepoPublic, true
	case RepoPullRequestTargetAllowed:
		return KindRepoPullRequestTargetAllowed, true
	case RepoWikiOpen:
		return KindRepoWikiOpen, true
	case RequestDestinationTrusted:
		return KindRequestDestinationTrusted, true
	case TestCommit:
		return KindTestCommit, true
	case TestFlag:
		return KindTestFlag, true
	case TestList:
		return KindTestList, true
	case TestRepoFlag:
		return KindTestRepoFlag, true
	case TestText:
		return KindTestText, true
	case WorkflowDefinition:
		return KindWorkflowDefinition, true
	}
	return KindUnset, false
}

// WithRepo is q naming the repository r (none, when r is zero), when the
// kind of q has a repo that may be left out; ok is false of another kind.
func WithRepo(q Query, r Repo) (_ Query, ok bool) {
	switch q := q.(type) {
	case RepoAllowForking:
		q.Repo = r
		return q, true
	case RepoAllowedActions:
		q.Repo = r
		return q, true
	case RepoConfigurationVariables:
		q.Repo = r
		return q, true
	case RepoDefaultTokenWrite:
		q.Repo = r
		return q, true
	case RepoEnvironmentConfigurationVariables:
		q.Repo = r
		return q, true
	case RepoEnvironmentProtected:
		q.Repo = r
		return q, true
	case RepoForkPRAppChecks:
		q.Repo = r
		return q, true
	case RepoForkPRRunWorkflows:
		q.Repo = r
		return q, true
	case RepoForkPRSecrets:
		q.Repo = r
		return q, true
	case RepoForkPRWriteTokens:
		q.Repo = r
		return q, true
	case RepoMergeCommitAppChecks:
		q.Repo = r
		return q, true
	case RepoPublic:
		q.Repo = r
		return q, true
	case RepoPullRequestTargetAllowed:
		q.Repo = r
		return q, true
	case RepoWikiOpen:
		q.Repo = r
		return q, true
	}
	return q, false
}

